// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Draft history"
// Changes: History operations of a session opened on a draft (fake transport): a named version and a restore go to
//          the draft's own history, the restored draft replaces what the open draft view shows, the project is untouched.

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { defaultProjectData } from './project'
import { createProjectSession } from './projectSession'
import { createFakeTransport } from './projectTransport.fake'
import type { ProjectRecord } from '#/server/projects.server'

const project = (): ProjectRecord => ({
  id: 'p1',
  name: 'Výrazy',
  data: { ...defaultProjectData(), ll: { grammar: 'E -> id', input: 'id' } },
  revision: 3,
  createdAt: '2026-01-01T00:00:00.000Z',
  updatedAt: '2026-01-01T00:00:00.000Z',
  view: { llSim: { step: 0, speed: 1 } },
})

async function openDraft() {
  const fake = createFakeTransport(project())
  const draft = fake.createDraft('Oprava')
  fake.agentEdit(draft.id, { grammarRules: 'E -> a' })
  const session = createProjectSession((await fake.transport.loadDraft({ draftId: draft.id }))!, fake.transport)
  return { fake, draft, session, state: () => session.getState() }
}

beforeEach(() => vi.useFakeTimers())
afterEach(() => vi.useRealTimers())

describe("a draft's history from its open view", () => {
  it("saving a named version stores the draft's parts in the draft's history, not the project's", async () => {
    const { fake, draft, session } = await openDraft()
    const snapshot = await session.saveNamedVersion('Verzia A')
    expect(snapshot).toMatchObject({ label: 'Verzia A', kind: 'named' })
    expect(fake.draftSnapshots(draft.id)).toEqual([expect.objectContaining({ label: 'Verzia A', grammarRules: 'E -> a' })])
    expect(fake.server.snapshots).toEqual([])
    expect(fake.callsOf('createSnapshot')).toHaveLength(0)
  })

  it('restoring a version refreshes the open draft view with the restored draft; the project is untouched', async () => {
    const { fake, draft, session, state } = await openDraft()
    const snapshot = await session.saveNamedVersion('Verzia A')
    fake.agentEdit(draft.id, { grammarRules: 'E -> b' })

    await session.restoreVersion(snapshot.id)

    expect(state().data.ll).toEqual({ grammar: 'E -> a', input: 'id' })
    expect(state().draft).toMatchObject({ id: draft.id, revision: 4, lastChangedBy: 'human' })
    expect(state()).toMatchObject({ status: 'saved', unsaved: false })
    expect(fake.draftSnapshots(draft.id).map((s) => s.label)).toEqual(['Verzia A', 'Pred obnovením „Verzia A“'])
    expect(fake.server.record).toMatchObject({ revision: 3, data: project().data })
    expect(fake.callsOf('restore')).toHaveLength(0)
  })

  it('restoring a version that is gone refuses with a reason and keeps the view', async () => {
    const { session, state } = await openDraft()
    const before = state()
    await expect(session.restoreVersion(99)).rejects.toThrow('Verzia už neexistuje')
    expect(state()).toBe(before)
  })

  it('an ended draft refuses history operations with the reason', async () => {
    const { fake, draft, session } = await openDraft()
    fake.discardDraft(draft.id)
    await expect(session.saveNamedVersion('X')).rejects.toThrow(/ukončený/)
    await expect(session.restoreVersion(1)).rejects.toThrow(/ukončený/)
  })

  it('importing into a draft still refuses', async () => {
    const { fake, session } = await openDraft()
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Human edits drafts"
    // Changes: Drafts are editable now; the refusal says to import into the project instead.
    await expect(session.importData(defaultProjectData(), 'x')).rejects.toThrow(/importuj do projektu/)
    expect(fake.callsOf('replace')).toHaveLength(0)
  })
})
